// Rate limit + chuẩn hoá đầu vào từ widget
const MAX_PER_IP = 120;        // tin / 5 phút / IP (nhiều người dùng chung Wi-Fi sự kiện)
const MAX_PER_SESSION = 15;    // tin / 5 phút / phiên chat
const WINDOW_MS = 5 * 60 * 1000;
const MAX_LEN = 1200;          // ký tự / tin

const item = $input.first().json;
const body = item.body || {};
const chatInput = String(body.chatInput ?? '').trim();
const ip = String(item.headers?.['x-forwarded-for'] || '').split(',')[0].trim();
const sessionId = String(body.sessionId || '').slice(0, 100) || 'anon-' + (ip || 'unknown');
const now = Date.now();

const sd = $getWorkflowStaticData('global');
sd.hits = sd.hits || {};
for (const k of Object.keys(sd.hits)) {
  sd.hits[k] = sd.hits[k].filter(t => now - t < WINDOW_MS);
  if (sd.hits[k].length === 0) delete sd.hits[k];
}
const ipKey = ip ? 'ip:' + ip : null;
const sidKey = 'sid:' + (sessionId || 'none');
const count = k => (k && sd.hits[k] ? sd.hits[k].length : 0);

let blockReason = '';
if (!chatInput) blockReason = 'empty';
else if (chatInput.length > MAX_LEN) blockReason = 'long';
else if (count(sidKey) >= MAX_PER_SESSION || count(ipKey) >= MAX_PER_IP) blockReason = 'rate';

if (!blockReason) {
  for (const k of [ipKey, sidKey]) if (k) (sd.hits[k] = sd.hits[k] || []).push(now);
}
return [{ json: { chatInput, sessionId, blocked: !!blockReason, blockReason } }];

